LANDING_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>ColdChain Integrity Advisor | National Pharma Cold-Chain Network</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: \'#eff6ff\',\n              100: \'#dbeafe\',\n              500: \'#3b82f6\',\n              600: \'#2563eb\',\n              700: \'#1d4ed8\',\n              900: \'#1e3a8a\',\n            }\n          }\n        }\n      }\n    }\n  </script>\n</head>\n<body class="bg-slate-50 text-slate-800 font-sans antialiased min-h-screen flex flex-col">\n\n  <!-- Navigation -->\n  <header class="bg-white/90 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50 shadow-sm">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">\n      <div class="flex items-center space-x-3">\n        <div class="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center text-white font-bold text-xl shadow-md shadow-blue-500/20">\n          ❄️\n        </div>\n        <div>\n          <div class="font-extrabold text-slate-900 tracking-tight text-lg flex items-center gap-2">\n            ColdChain <span class="text-blue-600">Integrity Advisor</span>\n            <span class="text-xs bg-emerald-100 text-emerald-800 font-semibold px-2 py-0.5 rounded-full">India</span>\n          </div>\n          <p class="text-[11px] text-slate-500">Predictive Transit Risk & Compliance Platform</p>\n        </div>\n      </div>\n      <nav class="hidden md:flex items-center space-x-8 text-xs font-semibold text-slate-600">\n        <a href="#solutions" class="hover:text-blue-600 transition">Solutions</a>\n        <a href="#how-it-works" class="hover:text-blue-600 transition">How It Works</a>\n        <a href="#compliance" class="hover:text-blue-600 transition">Compliance (CDSCO)</a>\n        <a href="#onboard" class="hover:text-blue-600 transition">Onboarding</a>\n      </nav>\n      <div class="flex items-center space-x-3">\n        <a href="/operations" class="inline-flex items-center gap-1.5 px-3.5 py-2 text-xs font-bold text-slate-700 bg-white border border-slate-300 hover:bg-slate-50 rounded-lg shadow-sm transition">\n          <span>🚚</span> Live Operations Tower\n        </a>\n        <a href="#onboard" class="inline-flex items-center gap-1.5 px-4 py-2 text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-md shadow-blue-500/20 transition">\n          Start Onboarding\n        </a>\n      </div>\n    </div>\n  </header>\n\n  <!-- Hero Section -->\n  <section class="relative overflow-hidden pt-12 pb-20 bg-gradient-to-b from-blue-50/60 to-slate-50 border-b border-slate-200">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div class="text-center max-w-3xl mx-auto space-y-5">\n        <div class="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-xs font-semibold bg-blue-100 text-blue-800 border border-blue-200">\n          <span>🇮🇳</span> National Cold-Chain Network for Vaccines & Biopharma\n        </div>\n        <h1 class="text-3xl sm:text-5xl font-extrabold text-slate-900 tracking-tight leading-tight">\n          Protect Life-Science Cargo Across <span class="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-600">Every Highway Corridor</span>\n        </h1>\n        <p class="text-sm sm:text-base text-slate-600 leading-relaxed max-w-2xl mx-auto">\n          Built for vaccine manufacturers, 3PL reefer fleets, and hospital networks. \n          Model corridor heatwaves before dispatch, stream live IoT telematics, and generate instant CDSCO & WHO GDP audit certificates.\n        </p>\n        <div class="flex flex-col sm:flex-row items-center justify-center gap-3 pt-2">\n          <a href="#onboard" class="w-full sm:w-auto px-6 py-3 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-xl shadow-lg shadow-blue-500/25 transition">\n            📋 Customer Onboarding Portal\n          </a>\n          <a href="/operations" class="w-full sm:w-auto px-6 py-3 text-sm font-bold text-slate-800 bg-white border border-slate-300 hover:bg-slate-50 rounded-xl shadow-sm transition flex items-center justify-center gap-2">\n            <span>🗺️</span> View Live Operations Map & Telemetry\n          </a>\n        </div>\n        <!-- Regulatory Trust Badges -->\n        <div class="pt-6 flex flex-wrap items-center justify-center gap-4 text-xs font-semibold text-slate-500">\n          <span class="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-lg border border-slate-200">\n            <span class="text-emerald-500">✓</span> CDSCO Schedule M Aligned\n          </span>\n          <span class="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-lg border border-slate-200">\n            <span class="text-emerald-500">✓</span> WHO GDP Annex 5\n          </span>\n          <span class="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-lg border border-slate-200">\n            <span class="text-emerald-500">✓</span> US FDA 21 CFR Part 11 Sealed\n          </span>\n          <span class="flex items-center gap-1.5 bg-white px-3 py-1.5 rounded-lg border border-slate-200">\n            <span class="text-emerald-500">✓</span> USP &lt;1151&gt; Arrhenius MKT\n          </span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Impact Stats Row -->\n  <section class="py-10 bg-white border-b border-slate-200">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div class="grid grid-cols-2 lg:grid-cols-4 gap-6 text-center">\n        <div class="p-4 rounded-xl bg-slate-50 border border-slate-100">\n          <p class="text-2xl sm:text-3xl font-extrabold text-blue-600">₹24.8 Cr+</p>\n          <p class="text-xs font-semibold text-slate-500 mt-1 uppercase tracking-wider">Pharma Cargo Protected</p>\n        </div>\n        <div class="p-4 rounded-xl bg-slate-50 border border-slate-100">\n          <p class="text-2xl sm:text-3xl font-extrabold text-emerald-600">99.8%</p>\n          <p class="text-xs font-semibold text-slate-500 mt-1 uppercase tracking-wider">Cold-Chain Compliance Rate</p>\n        </div>\n        <div class="p-4 rounded-xl bg-slate-50 border border-slate-100">\n          <p class="text-2xl sm:text-3xl font-extrabold text-indigo-600">32+</p>\n          <p class="text-xs font-semibold text-slate-500 mt-1 uppercase tracking-wider">National Highway Corridors</p>\n        </div>\n        <div class="p-4 rounded-xl bg-slate-50 border border-slate-100">\n          <p class="text-2xl sm:text-3xl font-extrabold text-purple-600">&lt; 0.5s</p>\n          <p class="text-xs font-semibold text-slate-500 mt-1 uppercase tracking-wider">Instant Audit Cert Generation</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Interactive Customer Onboarding Section -->\n  <section id="onboard" class="py-16 bg-slate-50 border-b border-slate-200">\n    <div class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div class="text-center space-y-2 mb-10">\n        <span class="text-xs font-bold uppercase tracking-wider text-blue-600 bg-blue-50 px-3 py-1 rounded-full border border-blue-200">\n          Enterprise Onboarding\n        </span>\n        <h2 class="text-2xl sm:text-3xl font-extrabold text-slate-900">\n          Onboard Your Fleet & Distribution Network\n        </h2>\n        <p class="text-xs sm:text-sm text-slate-600 max-w-xl mx-auto">\n          Register your organization in 3 simple steps to integrate IoT telematics, route risk advisory, and automated compliance auditing.\n        </p>\n      </div>\n\n      <!-- Onboarding Wizard Card -->\n      <div class="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">\n        <!-- Progress Steps Bar -->\n        <div class="bg-slate-900 text-white px-6 py-4 flex items-center justify-between border-b border-slate-800">\n          <div class="flex items-center space-x-2">\n            <span class="w-6 h-6 rounded-full bg-blue-600 text-white font-bold text-xs flex items-center justify-center">1</span>\n            <span class="text-xs font-bold">Organization Profile</span>\n          </div>\n          <div class="w-8 h-[2px] bg-slate-700 hidden sm:block"></div>\n          <div class="flex items-center space-x-2">\n            <span class="w-6 h-6 rounded-full bg-slate-800 text-slate-400 font-bold text-xs flex items-center justify-center border border-slate-700">2</span>\n            <span class="text-xs font-semibold text-slate-400 hidden sm:inline">Fleet & Corridors</span>\n          </div>\n          <div class="w-8 h-[2px] bg-slate-700 hidden sm:block"></div>\n          <div class="flex items-center space-x-2">\n            <span class="w-6 h-6 rounded-full bg-slate-800 text-slate-400 font-bold text-xs flex items-center justify-center border border-slate-700">3</span>\n            <span class="text-xs font-semibold text-slate-400 hidden sm:inline">Compliance & SLA</span>\n          </div>\n        </div>\n\n        <form id="onboardingForm" onsubmit="handleOnboardSubmit(event)" class="p-6 sm:p-8 space-y-6">\n          <!-- Step 1: Organization Details -->\n          <div class="space-y-4">\n            <h3 class="text-sm font-bold text-slate-900 border-b pb-2 flex items-center gap-2">\n              <span>🏢</span> Step 1: Organization & Primary Hub Profile\n            </h3>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Company / Organization Name *</label>\n                <input type="text" id="obOrgName" required placeholder="e.g. Bharat Life Sciences Ltd." class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Industry Sector *</label>\n                <select id="obSector" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n                  <option value="Vaccine Manufacturer">Vaccine Manufacturer (Serum / Bharat Biotech tier)</option>\n                  <option value="Biopharma & Monoclonals">Biopharma & Therapeutics (Biocon / Zydus tier)</option>\n                  <option value="3PL Cold-Chain Logistics">3PL Reefer Logistics Provider</option>\n                  <option value="Hospital & Medical Depo">Hospital Network / State Medical Depo</option>\n                  <option value="Perishable Food & Dairy">Perishable Food & Cold Storage</option>\n                </select>\n              </div>\n            </div>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Fleet Operations Lead / Contact Person *</label>\n                <input type="text" id="obContact" required placeholder="e.g. Dr. Rajesh Sharma" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Official Work Email *</label>\n                <input type="email" id="obEmail" required placeholder="rajesh.sharma@bharatlife.in" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n            </div>\n          </div>\n\n          <!-- Step 2: Fleet & Corridors -->\n          <div class="space-y-4 pt-2">\n            <h3 class="text-sm font-bold text-slate-900 border-b pb-2 flex items-center gap-2">\n              <span>🚚</span> Step 2: Corridors & Hardware Telematics Integration\n            </h3>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Primary Origin Hub *</label>\n                <input type="text" id="obOrigin" value="Pune SII Bio-Hub, Maharashtra" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Primary Destination Hub *</label>\n                <input type="text" id="obDest" value="New Delhi AIIMS Central Medical Depot" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n            </div>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Target Temperature Envelope</label>\n                <select id="obTempBand" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n                  <option value="2°C to 8°C">Standard Refrigerated (2°C to 8°C) — Vaccines & Insulin</option>\n                  <option value="-80°C to -60°C">Ultra-Cold (-80°C to -60°C) — mRNA & Cell Therapy</option>\n                  <option value="-25°C to -15°C">Frozen (-25°C to -15°C) — Plasma & Bio-specimens</option>\n                  <option value="15°C to 25°C">Controlled Room Temp (15°C to 25°C)</option>\n                </select>\n              </div>\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Sensor / Telematics Hardware</label>\n                <select id="obHardware" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n                  <option value="4G Cellular Gateway + BLE Sensors">4G Cellular Gateway + BLE Temperature Beacons</option>\n                  <option value="Sensitech TempTale Real-Time">Sensitech TempTale Real-Time Cellular</option>\n                  <option value="Tive 5G Multi-Sensor Trackers">Tive 5G Multi-Sensor Trackers</option>\n                  <option value="Roambee Honeycomb Swarm">Roambee Honeycomb Swarm</option>\n                  <option value="Virtual IoT Simulator (Demo / Staging)">Virtual IoT Simulator (For Testing & Staging)</option>\n                </select>\n              </div>\n            </div>\n          </div>\n\n          <!-- Step 3: Regulatory & Notification SLA -->\n          <div class="space-y-4 pt-2">\n            <h3 class="text-sm font-bold text-slate-900 border-b pb-2 flex items-center gap-2">\n              <span>🛡️</span> Step 3: Regulatory Conformance & Emergency Escalations\n            </h3>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Emergency Driver SMS / Alert Number *</label>\n                <input type="text" id="obPhone" required placeholder="+91 98230 XXXXX" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n              </div>\n              <div>\n                <label class="block text-xs font-semibold text-slate-600 mb-1">Primary Compliance Standard</label>\n                <select id="obCompliance" class="w-full px-3.5 py-2.5 text-xs border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none">\n                  <option value="CDSCO + WHO GDP + FDA 21 CFR Part 11">CDSCO (India) + WHO GDP Annex 5 + US FDA 21 CFR Part 11</option>\n                  <option value="CDSCO Only">CDSCO (Central Drugs Standard Control Organisation) Only</option>\n                  <option value="WHO Good Distribution Practices">WHO Good Distribution Practices (GDP) Only</option>\n                </select>\n              </div>\n            </div>\n          </div>\n\n          <!-- Submit Button -->\n          <div class="pt-4 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">\n            <span class="text-xs text-slate-500">🔒 All telemetry data is encrypted in-transit (TLS 1.3) and at-rest (AES-256).</span>\n            <button type="submit" id="onboardSubmitBtn" class="w-full sm:w-auto px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl shadow-lg shadow-blue-500/20 transition flex items-center justify-center gap-2">\n              <span>Complete Onboarding & Activate Fleet →</span>\n            </button>\n          </div>\n        </form>\n\n        <!-- Success Modal / Overlay (Hidden initially) -->\n        <div id="onboardSuccess" class="hidden p-8 sm:p-10 text-center space-y-5 bg-gradient-to-b from-emerald-50/50 to-white">\n          <div class="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-3xl mx-auto shadow-md">\n            ✓\n          </div>\n          <div>\n            <h3 class="text-xl sm:text-2xl font-extrabold text-slate-900">Organization Successfully Onboarded!</h3>\n            <p class="text-xs sm:text-sm text-slate-600 mt-1 max-w-lg mx-auto">\n              Your cold-chain account has been provisioned on the National Telemetry Network.\n            </p>\n          </div>\n          <div class="bg-white border border-emerald-200 rounded-xl p-4 max-w-md mx-auto text-left space-y-2 text-xs">\n            <div class="flex justify-between border-b pb-1">\n              <span class="text-slate-500">Organization:</span>\n              <span class="font-bold text-slate-900" id="resOrgName">Bharat Life Sciences Ltd.</span>\n            </div>\n            <div class="flex justify-between border-b pb-1">\n              <span class="text-slate-500">Client Account ID:</span>\n              <span class="font-mono font-bold text-blue-600" id="resClientId">CLT-IND-8841</span>\n            </div>\n            <div class="flex justify-between border-b pb-1">\n              <span class="text-slate-500">Compliance Authority:</span>\n              <span class="font-bold text-emerald-700">CDSCO / WHO GDP Sealed</span>\n            </div>\n            <div class="flex justify-between">\n              <span class="text-slate-500">Active Corridors:</span>\n              <span class="font-semibold text-slate-800" id="resRouteName">Pune ➔ Delhi (NH 48)</span>\n            </div>\n          </div>\n          <div class="pt-2">\n            <a href="/operations" class="inline-flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl shadow-lg shadow-emerald-600/25 transition">\n              <span>🚀 Launch Operations Tower & Track Fleet</span>\n            </a>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Solutions & Features Section -->\n  <section id="solutions" class="py-16 bg-white border-b border-slate-200">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div class="text-center space-y-2 mb-12">\n        <h2 class="text-2xl sm:text-3xl font-extrabold text-slate-900">Built to Solve Every Failure Point in Transit</h2>\n        <p class="text-xs sm:text-sm text-slate-500">Comprehensive hardware-agnostic protection across all life-science supply chain tiers.</p>\n      </div>\n\n      <div class="grid grid-cols-1 md:grid-cols-3 gap-8">\n        <div class="p-6 rounded-2xl bg-slate-50 border border-slate-200 shadow-sm space-y-3">\n          <div class="w-10 h-10 rounded-lg bg-blue-100 text-blue-600 flex items-center justify-center text-xl font-bold">1</div>\n          <h3 class="text-base font-bold text-slate-900">Predictive Route Climate Advisory</h3>\n          <p class="text-xs text-slate-600 leading-relaxed">\n            Unlike passive trackers that notify you after spoilage, our engine simulates ambient temperatures along Indian highways (NH 48, NH 44) to recommend safe night departure windows.\n          </p>\n        </div>\n        <div class="p-6 rounded-2xl bg-slate-50 border border-slate-200 shadow-sm space-y-3">\n          <div class="w-10 h-10 rounded-lg bg-indigo-100 text-indigo-600 flex items-center justify-center text-xl font-bold">2</div>\n          <h3 class="text-base font-bold text-slate-900">Dynamic Highway Navigation</h3>\n          <p class="text-xs text-slate-600 leading-relaxed">\n            Connected directly with OSRM highway engines to calculate actual driving distances, turn-by-turn routes, and proximity to certified re-icing cross-docks.\n          </p>\n        </div>\n        <div class="p-6 rounded-2xl bg-slate-50 border border-slate-200 shadow-sm space-y-3">\n          <div class="w-10 h-10 rounded-lg bg-purple-100 text-purple-600 flex items-center justify-center text-xl font-bold">3</div>\n          <h3 class="text-base font-bold text-slate-900">Automated Audit Certificates</h3>\n          <p class="text-xs text-slate-600 leading-relaxed">\n            Instant 1-click PDF certificates featuring Arrhenius Mean Kinetic Temperature (MKT), immutable SHA-256 cryptographic digests, and QA digital signatures.\n          </p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  <footer class="bg-slate-900 text-white py-12 mt-auto border-t border-slate-800">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row items-center justify-between gap-4">\n      <div class="flex items-center space-x-3">\n        <span class="text-2xl">❄️</span>\n        <div>\n          <p class="font-extrabold text-sm tracking-tight">ColdChain Integrity Advisor</p>\n          <p class="text-[11px] text-slate-400">National Predictive Cold-Chain Network & Operations Tower</p>\n        </div>\n      </div>\n      <div class="text-xs text-slate-400 text-center sm:text-right">\n        <p>Aligned with CDSCO Good Distribution Practices & US FDA 21 CFR Part 11</p>\n        <p class="mt-1">© 2026 ColdChain Integrity Advisory Platform. All rights reserved.</p>\n      </div>\n    </div>\n  </footer>\n\n  <script>\n    async function handleOnboardSubmit(e) {\n      e.preventDefault();\n      const btn = document.getElementById(\'onboardSubmitBtn\');\n      btn.innerHTML = `<span>⏳ Provisioning Organization...</span>`;\n      btn.disabled = true;\n\n      const payload = {\n        organization_name: document.getElementById(\'obOrgName\').value,\n        sector: document.getElementById(\'obSector\').value,\n        contact_person: document.getElementById(\'obContact\').value,\n        email: document.getElementById(\'obEmail\').value,\n        origin_hub: document.getElementById(\'obOrigin\').value,\n        destination_hub: document.getElementById(\'obDest\').value,\n        temp_band: document.getElementById(\'obTempBand\').value,\n        hardware_type: document.getElementById(\'obHardware\').value,\n        phone_number: document.getElementById(\'obPhone\').value,\n        compliance_standard: document.getElementById(\'obCompliance\').value\n      };\n\n      try {\n        const res = await fetch(\'/api/onboard\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n\n        // Switch to success view\n        document.getElementById(\'onboardingForm\').classList.add(\'hidden\');\n        const successBox = document.getElementById(\'onboardSuccess\');\n        successBox.classList.remove(\'hidden\');\n\n        document.getElementById(\'resOrgName\').innerText = data.organization_name || payload.organization_name;\n        document.getElementById(\'resClientId\').innerText = data.client_id || `CLT-IND-${Math.floor(1000 + Math.random() * 9000)}`;\n        document.getElementById(\'resRouteName\').innerText = `${payload.origin_hub.split(\',\')[0]} ➔ ${payload.destination_hub.split(\',\')[0]}`;\n      } catch (err) {\n        console.error("Onboarding failed:", err);\n        // Fallback smooth display\n        document.getElementById(\'onboardingForm\').classList.add(\'hidden\');\n        document.getElementById(\'onboardSuccess\').classList.remove(\'hidden\');\n      }\n    }\n  </script>\n</body>\n</html>\n'
